H,W=18,14
out=[[8]*W for _ in range(H)]
# original object
obj=[[8,8,8,1,7],[8,1,0,0,1],[7,0,1,1,7]]
for i,row in enumerate(obj):
 for j,v in enumerate(row):
  if v!=8: out[2+i][8+j]=v
for r,c in [(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]:
 for i,row in enumerate(obj):
  for j,v in enumerate(row):
   if v!=8: out[r-2+i][c-1+j]=v
print('\n'.join(' '.join(map(str,row)) for row in out))

